mapper.select:
SELECT n.notice_id AS noticeId, n.notice_type AS noticeType, n.title AS title, n.scope AS scope, n.restore_time AS restoreTime, n.create_time AS createTime, CASE WHEN r.user_id IS NOT NULL THEN 1 ELSE 0 END AS readFlag FROM cs_notice n LEFT JOIN cs_notice_read r ON r.notice_id = n.notice_id AND r.user_id = #{userId} WHERE n.status = '1' AND n.create_time <= NOW()
AND n.notice_type = #{noticeType}
AND n.title LIKE CONCAT('%', #{title}, '%')
AND n.create_time >= #{publishTimeStart}
AND n.create_time <= #{publishTimeEnd}
AND r.user_id IS NOT NULL
AND r.user_id IS NULL
ORDER BY n.pinned DESC, n.create_time DESC
